// Notos' sounds, synthesized from scratch (no samples): node tools/notos-sounds.js dist/notos_music
// Everything here is generated by code: sine and bell oscillators, filtered noise for the wind,
// and a small reverb. Theme: Notos, the south wind. Key: D major.
'use strict';
const fs = require('fs');
const path = require('path');

const RATE = 48000;
const out = process.argv[2] || path.join(__dirname, 'out');
fs.mkdirSync(out, { recursive: true });

// ---- helpers

let seed = 0x9e3779b9;
function random() { // deterministic: the same sounds every run
  seed ^= seed << 13; seed >>>= 0; seed ^= seed >>> 17; seed ^= seed << 5; seed >>>= 0;
  return seed / 4294967296;
}
const note = (name) => {
  const m = /^([A-G])(#|b)?(\d)$/.exec(name);
  const base = { C: -9, D: -7, E: -5, F: -4, G: -2, A: 0, B: 2 }[m[1]];
  const semis = base + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0) + (Number(m[3]) - 4) * 12;
  return 440 * Math.pow(2, semis / 12);
};
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const smooth = (x) => { x = clamp(x, 0, 1); return x * x * (3 - 2 * x); };

function buffer(seconds) {
  const n = Math.round(seconds * RATE);
  return { L: new Float32Array(n), R: new Float32Array(n), n };
}

// A bell-like tone: a few partials, each with its own decay; `pan` -1..1.
function bell(buf, at, freq, { gain = 0.3, decay = 0.6, pan = 0, attack = 0.004, partials, detune = 0 } = {}) {
  const parts = partials || [[1, 1, 1], [2, 0.35, 0.6], [3.01, 0.12, 0.4], [4.2, 0.06, 0.25]];
  const start = Math.round(at * RATE);
  const length = Math.min(buf.n - start, Math.round((decay * 7 + attack) * RATE));
  const pl = Math.cos((pan + 1) * Math.PI / 4), pr = Math.sin((pan + 1) * Math.PI / 4);
  for (let i = 0; i < length; i++) {
    const t = i / RATE;
    const env = Math.min(1, t / attack);
    let v = 0;
    for (const [ratio, amp, dk] of parts) {
      const f = freq * ratio * (1 + detune * Math.sin(t * 5.3));
      v += amp * Math.sin(2 * Math.PI * f * t) * Math.exp(-t / (decay * dk));
    }
    buf.L[start + i] += v * env * gain * pl;
    buf.R[start + i] += v * env * gain * pr;
  }
}

// A soft pad: detuned sines (and a touch of the octave) under a slow envelope.
function pad(buf, at, seconds, freqs, { gain = 0.08, attack = 0.4, release = 0.6, width = 0.6 } = {}) {
  const start = Math.round(at * RATE);
  const length = Math.min(buf.n - start, Math.round(seconds * RATE));
  freqs.forEach((freq, k) => {
    const pan = ((k / Math.max(1, freqs.length - 1)) * 2 - 1) * width;
    const pl = Math.cos((pan + 1) * Math.PI / 4), pr = Math.sin((pan + 1) * Math.PI / 4);
    const phase = random() * 6.28;
    for (let i = 0; i < length; i++) {
      const t = i / RATE;
      const env = smooth(t / attack) * smooth((seconds - t) / release);
      const v = Math.sin(2 * Math.PI * freq * 1.0015 * t + phase) + Math.sin(2 * Math.PI * freq * 0.9985 * t)
              + 0.25 * Math.sin(2 * Math.PI * freq * 2 * t + phase);
      buf.L[start + i] += v * env * gain * pl * 0.45;
      buf.R[start + i] += v * env * gain * pr * 0.45;
    }
  });
}

// Wind: noise through a resonant band-pass whose centre, loudness and side follow the curves
// given (functions of 0..1 over the gust).
function wind(buf, at, seconds, { freq, level, pan = () => 0, q = 1.6, gain = 0.5 }) {
  const start = Math.round(at * RATE);
  const length = Math.min(buf.n - start, Math.round(seconds * RATE));
  let low = 0, band = 0, lowR = 0, bandR = 0, brown = 0;
  for (let i = 0; i < length; i++) {
    const u = i / length;
    const f = freq(u);
    const k = 2 * Math.sin(Math.PI * Math.min(f, RATE / 6) / RATE);
    const damp = 1 / q;
    brown = 0.985 * brown + 0.06 * (random() * 2 - 1);
    const white = random() * 2 - 1;
    const input = 0.6 * white + 0.4 * brown * 4;
    // a slightly different filter per side gives width
    low += k * band; const high = input - low - damp * band; band += k * high;
    const inputR = 0.6 * (random() * 2 - 1) + 0.4 * brown * 4;
    lowR += k * 1.03 * bandR; const highR = inputR - lowR - damp * bandR; bandR += k * 1.03 * highR;
    const p = clamp(pan(u), -1, 1);
    const pl = Math.cos((p + 1) * Math.PI / 4), pr = Math.sin((p + 1) * Math.PI / 4);
    const a = level(u) * gain;
    buf.L[start + i] += band * a * pl;
    buf.R[start + i] += bandR * a * pr;
  }
}

// A gliding tone (the wind's whistle): pitch follows freq(u), with a gentle shimmer.
function glide(buf, at, seconds, { freq, level, gain = 0.1, pan = 0 }) {
  const start = Math.round(at * RATE);
  const length = Math.min(buf.n - start, Math.round(seconds * RATE));
  const pl = Math.cos((pan + 1) * Math.PI / 4), pr = Math.sin((pan + 1) * Math.PI / 4);
  let phase = 0, phase2 = 0;
  for (let i = 0; i < length; i++) {
    const u = i / length;
    const f = freq(u);
    phase += 2 * Math.PI * f / RATE;
    phase2 += 2 * Math.PI * f * 1.004 / RATE;
    const v = (Math.sin(phase) + Math.sin(phase2) + 0.2 * Math.sin(2 * phase)) * level(u) * gain * 0.5;
    buf.L[start + i] += v * pl;
    buf.R[start + i] += v * pr;
  }
}

// A small Schroeder reverb (comb filters into all-passes), mixed in at `wet`.
function reverb(buf, { wet = 0.25, size = 1, damping = 0.35 } = {}) {
  const combs = [1116, 1188, 1277, 1356].map((d) => Math.round(d * size * RATE / 44100));
  const passes = [556, 441].map((d) => Math.round(d * RATE / 44100));
  for (const [ch, spread] of [['L', 0], ['R', 23]]) {
    const x = buf[ch];
    const y = new Float32Array(buf.n);
    for (const d0 of combs) {
      const d = d0 + spread;
      const line = new Float32Array(d);
      let idx = 0, filt = 0;
      const fb = 0.78 + 0.06 * Math.min(1, size - 0.5);
      for (let i = 0; i < buf.n; i++) {
        const o = line[idx];
        filt = o * (1 - damping) + filt * damping;
        line[idx] = x[i] + filt * fb;
        idx = (idx + 1) % d;
        y[i] += o * 0.25;
      }
    }
    let z = y;
    for (const d0 of passes) {
      const d = d0 + spread;
      const line = new Float32Array(d);
      const next = new Float32Array(buf.n);
      let idx = 0;
      for (let i = 0; i < buf.n; i++) {
        const o = line[idx];
        next[i] = -z[i] + o;
        line[idx] = z[i] + o * 0.5;
        idx = (idx + 1) % d;
      }
      z = next;
    }
    for (let i = 0; i < buf.n; i++) x[i] = x[i] * (1 - wet * 0.5) + z[i] * wet;
  }
}

// Peak to `db` dBFS, a soft knee against any overshoot, short fades at both ends.
function finish(buf, db, fadeOut = 0.02) {
  let peak = 1e-9;
  for (let i = 0; i < buf.n; i++) peak = Math.max(peak, Math.abs(buf.L[i]), Math.abs(buf.R[i]));
  const g = Math.pow(10, db / 20) / peak;
  const fi = Math.round(0.002 * RATE), fo = Math.round(fadeOut * RATE);
  for (let i = 0; i < buf.n; i++) {
    let e = 1;
    if (i < fi) e = i / fi;
    if (i > buf.n - fo) e = Math.min(e, (buf.n - i) / fo);
    buf.L[i] = Math.tanh(buf.L[i] * g * 1.05) * e;
    buf.R[i] = Math.tanh(buf.R[i] * g * 1.05) * e;
  }
}

function write(name, buf) {
  const data = Buffer.alloc(buf.n * 4);
  for (let i = 0; i < buf.n; i++) {
    data.writeInt16LE(Math.round(clamp(buf.L[i], -1, 1) * 32767), i * 4);
    data.writeInt16LE(Math.round(clamp(buf.R[i], -1, 1) * 32767), i * 4 + 2);
  }
  const head = Buffer.alloc(44);
  head.write('RIFF', 0); head.writeUInt32LE(36 + data.length, 4); head.write('WAVE', 8);
  head.write('fmt ', 12); head.writeUInt32LE(16, 16); head.writeUInt16LE(1, 20); head.writeUInt16LE(2, 22);
  head.writeUInt32LE(RATE, 24); head.writeUInt32LE(RATE * 4, 28); head.writeUInt16LE(4, 32); head.writeUInt16LE(16, 34);
  head.write('data', 36); head.writeUInt32LE(data.length, 40);
  fs.writeFileSync(path.join(out, name + '.wav'), Buffer.concat([head, data]));
  console.log(`${name}.wav  ${(buf.n / RATE).toFixed(2)} s`);
}

// ---- the sounds

// move: a light, airy tick between covers.
{
  const b = buffer(0.09);
  bell(b, 0, note('A6'), { gain: 0.5, decay: 0.012, partials: [[1, 1, 1], [2.0, 0.25, 0.6]] });
  bell(b, 0, note('D6'), { gain: 0.25, decay: 0.016, partials: [[1, 1, 1]] });
  wind(b, 0, 0.03, { freq: () => 6000, level: (u) => (1 - u) * (1 - u), q: 2, gain: 0.08 });
  finish(b, -10, 0.015);
  write('move', b);
}

// select: a bright two-note pop, rising a fifth.
{
  const b = buffer(0.26);
  bell(b, 0, note('A5'), { gain: 0.45, decay: 0.05, pan: -0.15 });
  bell(b, 0.055, note('E6'), { gain: 0.5, decay: 0.07, pan: 0.15 });
  reverb(b, { wet: 0.18, size: 0.6 });
  finish(b, -7, 0.05);
  write('select', b);
}

// settings: a quick rising arpeggio, D major, with a soft breath of wind under it.
{
  const b = buffer(0.9);
  ['D5', 'F#5', 'A5', 'D6'].forEach((n, i) =>
    bell(b, i * 0.065, note(n), { gain: 0.32, decay: 0.16, pan: -0.45 + i * 0.3 }));
  wind(b, 0, 0.55, { freq: (u) => 700 + 1400 * u, level: (u) => Math.sin(Math.PI * u), pan: (u) => -0.6 + 1.2 * u, gain: 0.05 });
  reverb(b, { wet: 0.3, size: 0.85 });
  finish(b, -6, 0.2);
  write('settings', b);
}

// home: a gust crossing the screen, with a warm chord settling in behind it.
{
  const b = buffer(1.35);
  wind(b, 0, 1.15, { freq: (u) => 450 + 1500 * Math.sin(Math.PI * u * 0.9), level: (u) => Math.pow(Math.sin(Math.PI * u), 1.5),
                     pan: (u) => -0.85 + 1.7 * u, gain: 0.32 });
  pad(b, 0.12, 1.2, [note('D4'), note('A4'), note('E5'), note('F#5')], { gain: 0.07, attack: 0.35, release: 0.6 });
  bell(b, 0.42, note('A5'), { gain: 0.16, decay: 0.25, pan: 0.3 });
  bell(b, 0.5, note('D6'), { gain: 0.12, decay: 0.3, pan: 0.5 });
  reverb(b, { wet: 0.35, size: 1 });
  finish(b, -5, 0.25);
  write('home', b);
}

// loading: the wind lifting off. A gust rises in pitch and strength, a whistle glides up through
// it, and it opens on a bright chord.
{
  const b = buffer(4.2);
  wind(b, 0, 3.4, { freq: (u) => 280 * Math.pow(12, u), level: (u) => 0.15 + 0.85 * smooth(u * 1.1) * (1 - smooth((u - 0.92) / 0.08)),
                    pan: (u) => 0.35 * Math.sin(u * 9), gain: 0.3, q: 2.2 });
  glide(b, 0.25, 3.0, { freq: (u) => note('D4') * Math.pow(4, smooth(u)), level: (u) => smooth(u * 2) * (1 - smooth((u - 0.85) / 0.15)), gain: 0.07 });
  // sparkles rising with it
  ['D6', 'E6', 'F#6', 'A6', 'B6', 'D7'].forEach((n, i) =>
    bell(b, 1.0 + i * 0.36, note(n), { gain: 0.06 + i * 0.012, decay: 0.12, pan: i % 2 ? 0.5 : -0.5 }));
  // the arrival
  [['D5', -0.4], ['F#5', -0.15], ['A5', 0.15], ['D6', 0.4]].forEach(([n, p]) =>
    bell(b, 3.3, note(n), { gain: 0.2, decay: 0.32, pan: p }));
  pad(b, 3.2, 1.0, [note('D4'), note('A4'), note('F#5')], { gain: 0.06, attack: 0.08, release: 0.8 });
  reverb(b, { wet: 0.35, size: 1.1 });
  finish(b, -4, 0.3);
  write('loading', b);
}

// startup: Notos arriving. Wind gathers from nothing, bells fall in like light (the emblem
// appearing), a chord blooms as "Notos" settles, and it all breathes out.
{
  const b = buffer(6.3);
  wind(b, 0, 2.6, { freq: (u) => 300 + 900 * smooth(u), level: (u) => smooth(u * 1.6) * (1 - smooth((u - 0.6) / 0.4)),
                    pan: (u) => -0.7 + 1.4 * u, gain: 0.26 });
  wind(b, 2.0, 4.0, { freq: (u) => 900 - 500 * u, level: (u) => 0.35 * smooth(u * 3) * (1 - smooth(u)), pan: (u) => 0.5 - u, gain: 0.18 });
  // falling bells (D major pentatonic)
  const fall = ['A6', 'F#6', 'E6', 'D6', 'B5', 'A5'];
  fall.forEach((n, i) => bell(b, 0.6 + i * 0.16, note(n), { gain: 0.12 + i * 0.02, decay: 0.3, pan: 0.6 - i * 0.24 }));
  // the bloom
  pad(b, 1.5, 4.6, [note('D3'), note('A3'), note('D4'), note('F#4'), note('A4'), note('E5')],
      { gain: 0.085, attack: 0.9, release: 2.2, width: 0.8 });
  [['D4', -0.3], ['A4', 0.3], ['F#5', -0.1], ['A5', 0.2], ['D6', 0]].forEach(([n, p], i) =>
    bell(b, 2.05 + i * 0.05, note(n), { gain: 0.2, decay: 0.6, pan: p }));
  // a last glint as the name settles
  bell(b, 3.3, note('E6'), { gain: 0.1, decay: 0.45, pan: 0.4 });
  bell(b, 3.45, note('A6'), { gain: 0.09, decay: 0.55, pan: -0.3 });
  reverb(b, { wet: 0.42, size: 1.2, damping: 0.4 });
  finish(b, -3, 1.2);
  write('startup', b);
}
